'use strict';
const STORE='niems_pim_2570_v1';
const emptyState=()=>({version:1,task:{},proc:{},monthly:{},contracts:[],people:[],assignments:[],outcomes:{},evidence:[],risks:[],logs:[],lastSaved:null});
let db=emptyState(), page='overview', search='', group='all', ganttGroup='all', budgetCategory='all', procFilter='all', sideOpen=false;
const navItems=[['overview','▦','ภาพรวมบริหาร'],['gantt','▤','แผนงานรายเดือน'],['tasks','◈','35 ภารกิจ'],['proc','▣','จัดซื้อจัดจ้าง'],['budget','◉','งบประมาณและการเงิน'],['contracts','◧','สัญญาและการตรวจรับ'],['people','♙','กำลังคนและภาระงาน'],['outcomes','◎','ผลผลิตและผลสัมฤทธิ์'],['evidence','♧','หลักฐานและเอกสาร'],['risks','⚑','ความเสี่ยงและประเด็น'],['audit','☷','ประวัติและศูนย์ข้อมูล']];
const fiscalMonths=SEED.months;
const bangMonth=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=esc;
const baht=n=>n===null||n===undefined||n===''?'—':Number(n).toLocaleString('th-TH',{maximumFractionDigits:2});
const million=n=>Number(n/1000000).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2});
const fmtNum=n=>n===null||n===undefined||n===''?'—':Number(n).toLocaleString('th-TH',{maximumFractionDigits:2});
const monthBE=s=>{if(!s)return '—';let [y,m]=String(s).split('-');return bangMonth[Number(m)-1]+' '+String(y).slice(-2)};
const isoToBE=s=>{if(!s)return '—';let [y,m,d]=s.split('-');return d+' '+bangMonth[Number(m)-1]+' '+(Number(y)+543)};
const monthTodayBE=()=>{let d=new Date();return (d.getFullYear()+543)+'-'+String(d.getMonth()+1).padStart(2,'0')};
const contains=(...parts)=>!search||parts.some(p=>String(p??'').toLowerCase().includes(search.toLowerCase()));
const statusList=['ยังไม่รายงาน','เตรียมดำเนินการ','อยู่ระหว่างดำเนินการ','รอตรวจสอบ/ตรวจรับ','แล้วเสร็จ','ชะลอ/ติดขัด','ยกเลิก'];
const statusColor=s=>({'แล้วเสร็จ':'teal','อยู่ระหว่างดำเนินการ':'blue','รอตรวจสอบ/ตรวจรับ':'gold','ชะลอ/ติดขัด':'red','ยกเลิก':'red','เตรียมดำเนินการ':'grey','ยังไม่รายงาน':'grey'}[s]||'grey');
const tag=(name,kind='grey')=>`<span class="tag ${kind}">${esc(name)}</span>`;
const statusTag=s=>tag(s||'ยังไม่รายงาน',statusColor(s));
const taskBy=id=>SEED.workstreams.find(t=>t.id===id);
const procBy=id=>SEED.procurements.find(t=>t.id===id);
const option=(value,label,selected)=>`<option value="${attr(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`;
const sel=(name,items,selected,placeholder='— เลือก —')=>`<select class="f-input" name="${attr(name)}"><option value="">${placeholder}</option>${items.map(v=>option(v,v,selected)).join('')}</select>`;
const fld=(label,name,value='',type='text',more='')=>`<div class="fgroup"><label for="f_${attr(name)}">${label}</label><input class="f-input" id="f_${attr(name)}" name="${attr(name)}" type="${type}" value="${attr(value)}" ${more}></div>`;
const textarea=(label,name,value='')=>`<div class="fgroup full"><label>${label}</label><textarea class="f-input" name="${attr(name)}" rows="3">${esc(value)}</textarea></div>`;
const pghead=(heading,desc,actions='')=>`<div class="page-header"><div><h1>${heading}</h1><p>${desc}</p></div>${actions?`<div class="inlineform">${actions}</div>`:''}</div>`;
const panel=(heading,body,sub='',extra='')=>`<section class="panel"><div class="panel-head"><div><h2>${heading}</h2>${sub?`<p>${sub}</p>`:''}</div>${extra}</div>${body}</section>`;
const metric=(title,value,foot,color='')=>`<div class="metric"><div class="metric-label">${title}</div><div class="metric-value" style="${color?'color:'+color:''}">${value}</div><div class="metric-foot">${foot}</div></div>`;
const action=(label,act='addquick',cls='primary',id='')=>`<button class="btn ${cls} sm" data-action="${attr(act)}" ${id?`data-id="${attr(id)}"`:''}>${label}</button>`;
function getProcActual(p){let z=db.proc[p.id]||{};let rel=db.contracts.filter(c=>c.procId===p.id);let amounts=rel.map(c=>readNum(c.amount)).filter(v=>v!==null);let pays=rel.map(c=>readNum(c.paid)).filter(v=>v!==null);return {allocated:readNum(z.allocated),committed:amounts.length?amounts.reduce((a,b)=>a+b,0):readNum(z.committed),paid:pays.length?pays.reduce((a,b)=>a+b,0):readNum(z.paid),hasContract:rel.length>0,linked:!(!z.links||!z.links.length)};}
function readNum(v){if(v===null||v===undefined||v==='')return null;let x=Number(v);return Number.isFinite(x)?x:null;}
function saveLog(kind,target,text){db.logs.unshift({at:new Date().toISOString(),kind,target,text});db.logs=db.logs.slice(0,500);save();}
function save(){db.lastSaved=new Date().toISOString();try{localStorage.setItem(STORE,JSON.stringify(db));document.getElementById('lastsave').textContent='บันทึกล่าสุด '+new Date(db.lastSaved).toLocaleString('th-TH');}catch(e){notify('ไม่สามารถบันทึกลงเบราว์เซอร์ได้ กรุณาสำรองข้อมูลออกเป็นไฟล์',true);}}
function load(){try{let raw=localStorage.getItem(STORE);if(raw){let obj=JSON.parse(raw);if(obj.version===1){db={...emptyState(),...obj};}}}catch(e){console.warn('Load failed',e)}if(db.lastSaved)document.getElementById('lastsave').textContent='บันทึกล่าสุด '+new Date(db.lastSaved).toLocaleString('th-TH');}
function notify(msg,bad=false){let el=document.getElementById('toast');if(!el){el=document.createElement('div');el.id='toast';el.style='position:fixed;bottom:22px;right:20px;z-index:200;background:#102c4c;color:white;padding:13px 18px;border-radius:10px;max-width:min(430px,90vw);box-shadow:0 12px 40px #071d3955';document.body.append(el);}el.style.background=bad?'#aa3d49':'#102c4c';el.textContent=msg;el.style.display='block';clearTimeout(window.__toastTimer);window.__toastTimer=setTimeout(()=>{el.style.display='none'},3500);}
function renderNav(){document.getElementById('nav').innerHTML=navItems.map(([id,ico,label])=>`<button class="nav ${page===id?'active':''}" data-go="${id}"><span class="n-icon">${ico}</span><span>${label}</span></button>`).join('');}
function filteredTasks(){return SEED.workstreams.filter(t=>(group==='all'||t.group===group)&&contains(t.id,t.name,db.task[t.id]?.owner,db.task[t.id]?.notes));}
function filteredProcs(){return SEED.procurements.filter(p=>{let z=db.proc[p.id]||{};let groupOkay=group==='all'||(z.links||[]).some(i=>taskBy(i)?.group===group);return groupOkay&&contains(p.id,p.name,z.owner,z.notes)&& (procFilter==='all'||(procFilter==='unlinked'?!z.links?.length:procFilter==='notor'?!p.torDraft:z.status===procFilter))});}
function render(){renderNav();let html={overview:renderOverview,gantt:renderGantt,tasks:renderTasks,proc:renderProc,budget:renderBudget,contracts:renderContracts,people:renderPeople,outcomes:renderOutcomes,evidence:renderEvidence,risks:renderRisks,audit:renderAudit}[page]();document.getElementById('main').innerHTML=html;}
function planMonthBars(){let by={};SEED.procurements.forEach(p=>by[p.procureMonth]=(by[p.procureMonth]||0)+p.plannedAmount);let max=Math.max(...Object.values(by));return `<div class="stack">${Object.entries(by).sort(([a],[b])=>a.localeCompare(b)).map(([m,v])=>`<div class="barrow"><span>${monthBE(m)}</span><div class="bartrack"><div class="barfill" style="width:${(100*v/max).toFixed(2)}%"></div></div><span class="num">${million(v)} ลบ.</span></div>`).join('')}</div>`;}
function doughnut(){let inv=SEED.procurements.filter(p=>p.category==='ลงทุน').reduce((s,p)=>s+p.plannedAmount,0);let o=110502300-inv;let pct=(inv/110502300*100).toFixed(2);return `<div class="donut-wrap"><div class="donut" style="background:conic-gradient(#2059ae 0 ${pct}%,#24a79a ${pct}% 100%)"><div class="donut-in"><strong>${pct}%</strong><small>งบลงทุน</small></div></div><div class="legend"><div><b style="background:#2059ae"></b>งบลงทุน <strong>${million(inv)} ลบ.</strong></div><div><b style="background:#24a79a"></b>งบดำเนินงาน <strong>${million(o)} ลบ.</strong></div><div class="muted small">สัดส่วนจากแผนจัดซื้อจัดจ้าง</div></div></div>`;}
function milestones(){return `<div class="roadmap">${SEED.roadmap.map(r=>`<div class="road"><div class="road-q">${r.q} • ปีงบประมาณ 2570</div><div class="road-title">${r.title}</div><div class="road-desc">${r.detail}</div></div>`).join('')}</div>`;}
function headsUp(){let nTor=SEED.procurements.filter(p=>!p.torDraft).length;let unr=SEED.procurements.filter(p=>!db.proc[p.id]?.status).length;let ul=SEED.procurements.filter(p=>!db.proc[p.id]?.links?.length).length;let signed=db.contracts.length;return `<div class="stack"><div class="listline"><span>รายการไม่มีร่าง TOR ตามแบบฟอร์มต้นฉบับ</span>${tag(nTor+' รายการ','gold')}</div><div class="listline"><span>รายการที่ยังไม่บันทึกสถานะจริง</span>${tag(unr+' รายการ','gold')}</div><div class="listline"><span>รายการที่ยังไม่ยืนยันการเชื่อมกับภารกิจ</span>${tag(ul+' รายการ','grey')}</div><div class="listline"><span>สัญญาที่บันทึกแล้ว (ไม่ใช่จำนวนสัญญาจริงทั้งหมด)</span>${tag(signed+' รายการ',signed?'teal':'grey')}</div></div>`;}
function renderOverview(){let filledTasks=SEED.workstreams.filter(t=>db.task[t.id]?.status&&db.task[t.id]?.status!=='ยังไม่รายงาน').length,filledProc=SEED.procurements.filter(p=>db.proc[p.id]?.status&&db.proc[p.id]?.status!=='ยังไม่รายงาน').length;return pghead('Executive Intelligence','ภาพรวมแผนปฏิบัติงานและแผนจัดซื้อจัดจ้าง ปีงบประมาณ 2570',`<span class="tag blue">แหล่งข้อมูลต้นฉบับ 2 ชุด</span>`)+`<div class="notice"><span style="font-size:18px">ⓘ</span><div><b>คำอธิบายข้อมูล:</b> ตัวเลข 35 ภารกิจ / 33 รายการ / 110.50 ล้านบาท เป็นข้อมูลจากแผน ส่วนสถานะโครงการ สัญญา เบิกจ่าย กำลังคน และหลักฐานเป็นข้อมูลที่ต้องนำเข้าหรือบันทึกจริง <b>ไม่มีการสมมติผลดำเนินงานหรือเบิกจ่าย</b></div></div><div class="cards">${metric('งบประมาณตามแผน','110.50 <small style="font-size:14px">ลบ.</small>','ยอดรวมจาก 33 รายการ','#174d9a')}${metric('ภารกิจตามแผน','35','ITCO 23 / NDEMS 12')}${metric('รายการจัดซื้อจัดจ้าง','33','ลงทุน 9 / ดำเนินงาน 24')}${metric('บันทึกสถานะแล้ว',`${filledTasks}/35`,'ภารกิจที่มีรายงานจริง','#00877a')}</div><div class="cards">${metric('มีข้อมูลสถานะจัดซื้อฯ',`${filledProc}/33`,'ยังไม่รายงาน '+(33-filledProc)+' รายการ')}${metric('สัญญาที่บันทึก',String(db.contracts.length),'ฐานข้อมูลสัญญาภายในเครื่อง')}${metric('บุคลากรที่บันทึก',String(db.people.length),'ยังไม่เท่ากับกำลังคนทั้งสำนัก')}${metric('หลักฐานที่บันทึก',String(db.evidence.length),'เอกสารแนบและบันทึกประกอบ')}</div><div class="grid2">${panel('วงเงินตามประเภท',`<div class="panel-body">${doughnut()}</div>`,'อ้างอิงรายการจัดซื้อจัดจ้างต้นฉบับ')}${panel('ช่วงเวลาจัดซื้อจัดจ้าง',`<div class="panel-body">${planMonthBars()}</div>`,'กำหนดการจากแผน ไม่ใช่ยอดการเบิกจ่าย')}</div><div class="grid2">${panel('ประเด็นต้องติดตาม',`<div class="panel-body">${headsUp()}</div>`,'คำนวณจากความครบถ้วนของข้อมูลที่บันทึก')}${panel('ความคืบหน้าจากรายงานจริง',`<div class="panel-body">${actualCoverage()}</div>`,'แยกข้อมูลจริงออกจากระดับกิจกรรมตามแผน')}</div>${panel('Roadmap รายไตรมาส',`<div class="panel-body">${milestones()}</div>`,'ตามภาพแผนปฏิบัติงานปีงบประมาณ 2570')}${intelligencePanel()}<div class="footer-note">หมายเหตุ: ไม่มีการบันทึกสัญญาหรือผลเบิกจ่ายในเอกสารต้นฉบับ การไม่แสดงข้อมูลจริงไม่ได้หมายถึงไม่มีการดำเนินงาน</div>`;}
function intelligencePanel(){
 const jan=SEED.procurements.filter(p=>p.requiredMonth==='2570-01');
 const until=monthTodayBE();
 const noReport=SEED.procurements.filter(p=>p.procureMonth<=until&&!db.proc[p.id]?.status);
 const peak=SEED.procurements.filter(p=>['2569-11','2569-12'].includes(p.procureMonth));
 const five=SEED.procurements.toSorted((a,b)=>b.plannedAmount-a.plannedAmount).slice(0,5);
 return `<div class="grid2">${panel('Project Intelligence · จุดควบคุมสำคัญ',`<div class="panel-body"><div class="stack"><div class="listline"><span>รายการกำหนดต้องการใช้งาน ม.ค. 2570</span><strong>${jan.length} รายการ · ${million(jan.reduce((s,p)=>s+p.plannedAmount,0))} ลบ.</strong></div><div class="listline"><span>วงเงินจัดซื้อช่วง พ.ย.–ธ.ค. 2569</span><strong>${million(peak.reduce((s,p)=>s+p.plannedAmount,0))} ลบ.</strong></div><div class="listline"><span>รายการที่ถึงเดือนตามแผนแต่ยังไม่มีรายงานสถานะ</span>${tag(noReport.length+' รายการ','gold')}</div><div class="listline"><span>การรายงานผลรายเดือนที่บันทึก</span>${tag(Object.keys(db.monthly).length+'/420 เดือน-ภารกิจ','blue')}</div></div><div class="notice warn" style="margin-bottom:0">รายการถึงเดือนตามแผนแต่ยังไม่รายงาน ไม่ใช่หลักฐานว่าล่าช้าหรือไม่ได้ดำเนินการจริง</div></div>`,'เกณฑ์เวลาอ้างอิงเดือนปัจจุบันจากอุปกรณ์ของผู้ใช้')}${panel('โครงการวงเงินสูงที่ต้องติดตาม',`<div class="panel-body"><div class="stack">${five.map(p=>`<div class="listline"><span><button class="linkbtn" data-action="editProc" data-id="${p.id}">${p.id}</button> · ${esc(p.name).slice(0,73)}${p.name.length>73?'…':''}</span><strong>${million(p.plannedAmount)} ลบ.</strong></div>`).join('')}</div><p class="help">มูลค่า 5 รายการรวม ${million(five.reduce((s,p)=>s+p.plannedAmount,0))} ล้านบาท คิดเป็น ${(five.reduce((s,p)=>s+p.plannedAmount,0)/110502300*100).toFixed(2)}% ของวงเงินตามแผน</p></div>`,'จัดลำดับโดยวงเงินตามแผน ไม่ใช่ความเสี่ยงที่เกิดขึ้นจริง')}</div>`;
}
function actualCoverage(){let vals=SEED.workstreams.map(t=>readNum(db.task[t.id]?.progress)).filter(v=>v!==null);let avg=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null;let steps=SEED.workstreams.filter(t=>db.task[t.id]?.status==='แล้วเสร็จ').length;return `<div class="rec-grid"><div class="rec"><small>ความก้าวหน้าที่ผู้ใช้บันทึก</small><strong>${avg===null?'—':avg.toFixed(1)+'%'}</strong><small>เฉลี่ย ${vals.length}/35 ภารกิจที่กรอกเปอร์เซ็นต์</small></div><div class="rec"><small>ภารกิจรายงานว่าแล้วเสร็จ</small><strong>${steps}</strong><small>ตามสถานะที่ผู้ใช้กรอก</small></div><div class="rec"><small>รายการเบิกจ่ายที่มีข้อมูล</small><strong>${SEED.procurements.filter(p=>getProcActual(p).paid!==null).length}</strong><small>จากทั้งหมด 33 รายการ</small></div></div><div class="notice warn" style="margin-bottom:0">การคำนวณเฉลี่ยใช้เฉพาะรายการที่ผู้ใช้กรอกค่าแล้ว ไม่ใช่เปอร์เซ็นต์ความสำเร็จรวมทุกภารกิจ</div>`;}
function renderGantt(){let rows=SEED.workstreams.filter(t=>(ganttGroup==='all'||t.group===ganttGroup)&&(group==='all'||t.group===group)&&contains(t.name,t.id));let lines='';let last='';for(let t of rows){if(t.group!==last){lines+=`<tr class="secrow ${t.group==='NDEMS'?'teal':''}"><td colspan="14">${t.group==='ITCO'?'ITCO · กลุ่มงานพัฒนาดิจิทัลและการสื่อสาร':'NDEMS · กลุ่มงานสนับสนุนดิจิทัลและการสื่อสาร'}</td></tr>`;last=t.group;}let z=db.task[t.id]||{};lines+=`<tr><td class="sticky-code">${t.id}</td><td class="sticky-name"><button class="linkbtn" data-action="editTask" data-id="${t.id}">${esc(t.name)}</button><div class="small muted">${esc(z.owner||'ยังไม่ระบุผู้รับผิดชอบ')}</div></td>${t.plan.map((a,idx)=>{let mo=fiscalMonths[idx],done=db.monthly[t.id+':'+mo];return `<td><span class="phase ${t.group==='ITCO'?'it':'nd'}${a} ${done?'actual':''}" data-action="editMonth" data-id="${t.id}" data-month="${mo}" title="${t.id} ${monthBE(mo)}: ${a===1?'เตรียม/ต่อเนื่อง':a===2?'ดำเนินการ/ประสานงาน':'พัฒนา/ทดสอบ/ติดตาม'}${done?' · มีบันทึกผลจริง':''}"></span></td>`}).join('')}</tr>`;}let qButtons=['all','ITCO','NDEMS'].map(g=>`<button class="pill ${ganttGroup===g?'active':''}" data-action="ganttf" data-id="${g}">${g==='all'?'ทั้งหมด':g}</button>`).join('');return pghead('แผนปฏิบัติงานรายเดือน','35 ภารกิจ × 12 เดือน · แสดงระดับกิจกรรมตามแผน (ไม่ใช่สถานะความก้าวหน้าจริง)',action('＋ บันทึกผลรายเดือน','monthQuick','teal'))+panel('YEAR ACTION PLAN 2570',`<div class="panel-body" style="padding-bottom:10px"><div class="pills">${qButtons}</div><div class="notice" style="margin-bottom:2px">เลือกช่องเดือนเพื่อบันทึกความก้าวหน้าและหลักฐานของภารกิจเดือนนั้น · ช่องขอบสีทองหมายถึงมีบันทึกผลจริง</div></div><div class="ganttwrap"><table class="gantt"><thead><tr><th class="sticky-code">รหัส</th><th class="sticky-name">ภารกิจ / ผู้รับผิดชอบ</th>${fiscalMonths.map(m=>`<th>${monthBE(m)}</th>`).join('')}</tr></thead><tbody>${lines||'<tr><td colspan="14">ไม่พบภารกิจ</td></tr>'}</tbody></table></div><div class="panel-body"><div class="pills"><span class="tag">ITCO 1 · เตรียม/ต่อเนื่อง</span><span class="tag blue">ITCO 2 · ประสานงาน</span><span class="tag" style="background:#0c469e;color:white">ITCO 3 · พัฒนา/ทดสอบ</span><span class="tag teal">NDEMS · 3 ระดับโทนเขียว</span><span class="tag gold">ขอบทอง · มีบันทึกผลจริง</span></div></div>`,'รูปแบบสีอ้างอิงแนวทางจากภาพต้นฉบับ; ค่ารายภารกิจใน Dashboard เป็นการถ่ายทอดเชิงภาพโดยประมาณ');}
function renderTasks(){let ts=filteredTasks(),counts={ITCO:ts.filter(t=>t.group==='ITCO').length,NDEMS:ts.filter(t=>t.group==='NDEMS').length};return pghead('บริหารภารกิจและโครงการ','ทะเบียน 35 ภารกิจ เชื่อมเจ้าภาพ ความคืบหน้า งบประมาณและผลการดำเนินงาน',action('＋ เพิ่มบันทึกผลรายเดือน','monthQuick','teal'))+`<div class="cards">${metric('ภารกิจที่อยู่ในตัวกรอง',ts.length,'ITCO '+counts.ITCO+' / NDEMS '+counts.NDEMS)}${metric('มีผู้รับผิดชอบ',ts.filter(t=>db.task[t.id]?.owner).length,'ตามที่มีการบันทึก')}${metric('รายงานว่าแล้วเสร็จ',ts.filter(t=>db.task[t.id]?.status==='แล้วเสร็จ').length,'สถานะผู้ใช้บันทึก')}${metric('มีข้อมูลความก้าวหน้า',ts.filter(t=>readNum(db.task[t.id]?.progress)!==null).length,'จากภารกิจที่เลือก')}</div>`+panel('ทะเบียนภารกิจ',`<div class="tblwrap"><table class="tbl"><thead><tr><th>รหัส</th><th>กลุ่ม</th><th>ภารกิจ</th><th>สถานะจริง</th><th>ความก้าวหน้า</th><th>ผู้รับผิดชอบ</th><th>แก้ไข</th></tr></thead><tbody>${ts.map(t=>{let z=db.task[t.id]||{},pr=readNum(z.progress);return `<tr><td class="mono strong">${t.id}</td><td>${tag(t.group,t.group==='ITCO'?'blue':'teal')}</td><td class="namecol"><button class="linkbtn" data-action="editTask" data-id="${t.id}">${esc(t.name)}</button></td><td>${statusTag(z.status)}</td><td>${pr===null?'<span class="muted">— ยังไม่รายงาน</span>':`<div class="mini-progress"><div style="width:${Math.min(100,Math.max(0,pr))}%"></div></div><span class="small">${pr}%</span>`}</td><td>${esc(z.owner||'—')}</td><td>${action('แก้ไข','editTask','',t.id)}</td></tr>`}).join('')||'<tr><td colspan="7" class="empty">ไม่พบรายการตามตัวกรอง</td></tr>'}</tbody></table></div>`,'ความก้าวหน้าจะแสดงเมื่อผู้รับผิดชอบบันทึกเอง')+`<div class="footer-note">การเชื่อมโยงรายการจัดซื้อจัดจ้างกับภารกิจเป็นข้อมูลที่ต้องยืนยันในหน้ารายการจัดซื้อจัดจ้าง</div>`;}
function renderProc(){let ps=filteredProcs();let list=ps.map(p=>{let z=db.proc[p.id]||{},a=getProcActual(p);return `<tr><td class="mono strong">${p.id}</td><td class="namecol"><button class="linkbtn" data-action="editProc" data-id="${p.id}">${esc(p.name)}</button><div class="small muted">${esc(z.owner||'ยังไม่ระบุผู้รับผิดชอบ')}</div></td><td>${tag(p.category,p.category==='ลงทุน'?'blue':'teal')}</td><td class="right strong">${baht(p.plannedAmount)}</td><td>${monthBE(p.procureMonth)}</td><td>${monthBE(p.requiredMonth)}</td><td>${tag(p.torDraft?'มีร่าง':'ไม่มีร่าง',p.torDraft?'teal':'red')}</td><td>${statusTag(z.status)}</td><td>${z.links?.length?tag(z.links.length+' ภารกิจ','blue'):'<span class="muted">ยังไม่ยืนยัน</span>'}</td><td>${action('จัดการ','editProc','',p.id)}</td></tr>`}).join('');let amt=ps.reduce((s,p)=>s+p.plannedAmount,0),lacks=ps.filter(p=>!p.torDraft).length;return pghead('จัดซื้อจัดจ้างและการติดตาม','ทะเบียนกลาง 33 รายการ เชื่อม TOR ระยะเวลาจัดซื้อ งบประมาณ สัญญา และผู้รับผิดชอบ',action('⇩ ส่งออก CSV','csvProc','')+' '+action('＋ บันทึกสัญญา','addContract','teal'))+`<div class="cards">${metric('รายการที่แสดง',ps.length,'จากแผนต้นฉบับ 33 รายการ')}${metric('วงเงินตามตัวกรอง',million(amt)+' ลบ.','ตามแผน ยังไม่ใช่การจัดสรรจริง')}${metric('ไม่มีร่าง TOR',lacks,'ตามสถานะที่ระบุในเอกสาร')}${metric('เชื่อมภารกิจยืนยันแล้ว',ps.filter(p=>db.proc[p.id]?.links?.length).length,'กรอกและยืนยันโดยผู้ใช้งาน')}</div>`+panel('ทะเบียนแผนจัดซื้อจัดจ้าง',`<div class="panel-body"><div class="filters"><label class="small muted">ตัวกรองสถานะ</label><select class="field" id="procFilter">${[['all','ทุกรายการ'],['unlinked','ยังไม่เชื่อมภารกิจ'],['notor','ต้นฉบับไม่มีร่าง TOR'],...statusList.map(s=>[s,s])].map(([v,l])=>option(v,l,procFilter)).join('')}</select><span class="muted small">เมื่อเลือก ITCO/NDEMS ด้านบน จะแสดงเฉพาะรายการที่ยืนยันเชื่อมโยงกับกลุ่มงานนั้นแล้ว</span></div></div><div class="tblwrap"><table class="tbl"><thead><tr><th>รหัส</th><th>รายการ</th><th>ประเภท</th><th class="right">วงเงินแผน (บาท)</th><th>จัดซื้อ</th><th>ต้องการใช้</th><th>ร่าง TOR</th><th>สถานะจริง</th><th>เชื่อมโยง</th><th>จัดการ</th></tr></thead><tbody>${list||'<tr><td class="empty" colspan="10">ไม่พบรายการ</td></tr>'}</tbody></table></div>`,'รหัส Pxx กำหนดขึ้นเพื่ออ้างอิงภายใน Dashboard ตามลำดับรายการ 1–33');}
function renderBudget(){let ps=SEED.procurements.filter(p=>(budgetCategory==='all'||p.category===budgetCategory)&&(group==='all'||(db.proc[p.id]?.links||[]).some(i=>taskBy(i)?.group===group))&&contains(p.id,p.name));let budget=ps.reduce((s,p)=>s+p.plannedAmount,0),nAlloc=0,nCom=0,nPaid=0;let alloc=0,committed=0,paid=0;ps.forEach(p=>{let a=getProcActual(p);if(a.allocated!==null){alloc+=a.allocated;nAlloc++}if(a.committed!==null){committed+=a.committed;nCom++}if(a.paid!==null){paid+=a.paid;nPaid++}});let hasGroup=group==='all';return pghead('บริหารงบประมาณและการเงิน','เปรียบเทียบวงเงินแผนกับรายการจัดสรร ผูกพัน และเบิกจ่ายที่มีหลักฐานบันทึก',action('⇩ ส่งออก CSV','csvBudget',''))+`<div class="notice warn"><span>!</span><div>ยอดวงเงินแผนและยอดดำเนินการจริงเป็นคนละฐานข้อมูล ไม่ควรนำยอดสะสมของรายการที่ยังไม่มีข้อมูลจริงไปตีความว่าเป็น 0 บาท หากเชื่อมกลุ่มงานผ่านภารกิจ รายการที่ยังไม่ยืนยันความสัมพันธ์จะไม่ถูกนำมารวม</div></div><div class="panel"><div class="panel-body"><div class="filters"><b class="small">ประเภทงบ:</b><select class="field" id="budgetCategory">${[['all','ทุกประเภท'],['ลงทุน','งบลงทุน'],['ดำเนินงาน','งบดำเนินงาน']].map(([v,l])=>option(v,l,budgetCategory)).join('')}</select><span class="muted small">แสดง ${ps.length} รายการ</span></div></div></div><div class="cards">${metric('วงเงินตามแผน',million(budget)+' ลบ.','ตามรายการจัดซื้อจัดจ้าง','#1f5bb4')}${metric('ได้รับจัดสรร (บันทึก)',nAlloc?million(alloc)+' ลบ.':'—','ข้อมูล '+nAlloc+'/'+ps.length+' รายการ')}${metric('ผูกพันตามข้อมูลที่บันทึก',nCom?million(committed)+' ลบ.':'—','ข้อมูล '+nCom+'/'+ps.length+' รายการ')}${metric('เบิกจ่ายตามข้อมูลที่บันทึก',nPaid?million(paid)+' ลบ.':'—','ข้อมูล '+nPaid+'/'+ps.length+' รายการ')}</div><div class="grid2">${panel('โครงสร้างงบประมาณ',`<div class="panel-body">${doughnut()}</div>`,'สัดส่วนแผนรวมทั้งสำนัก (ไม่เปลี่ยนตามตัวกรอง)')}${panel('ภาระจัดซื้อจัดจ้างตามเดือน',`<div class="panel-body">${budgetMonthBars(ps)}</div>`,'วงเงินแผนตามตัวกรอง')}</div>`+panel('บัญชีการเงินรายรายการ',`<div class="tblwrap"><table class="tbl"><thead><tr><th>รหัส</th><th>รายการ</th><th class="right">แผน</th><th class="right">จัดสรรจริง</th><th class="right">ผูกพัน</th><th class="right">เบิกจ่าย</th><th>ข้อมูล</th></tr></thead><tbody>${ps.map(p=>{let a=getProcActual(p);let k=[a.allocated,a.committed,a.paid].filter(v=>v!==null).length;return `<tr><td><button class="linkbtn mono" data-action="editProc" data-id="${p.id}">${p.id}</button></td><td class="namecol">${esc(p.name)}</td><td class="right">${baht(p.plannedAmount)}</td><td class="right">${baht(a.allocated)}</td><td class="right">${baht(a.committed)}</td><td class="right">${baht(a.paid)}</td><td>${tag(k+'/3 ช่อง',k===3?'teal':'grey')}</td></tr>`}).join('')||'<tr><td colspan="7" class="empty">ไม่มีรายการในตัวกรอง</td></tr>'}</tbody></table></div>`,'วงเงินผูกพัน/เบิกจ่ายใช้ข้อมูลสัญญาที่เชื่อมโยงเมื่อมี มิฉะนั้นใช้ค่าที่ผู้ใช้กรอกในทะเบียนจัดซื้อ')+`<div class="footer-note">ข้อควรระวัง: รายการสัญญามากกว่า 1 สัญญาอาจอยู่ภายใต้งบรายการเดียว ระบบรวมยอดสัญญาที่บันทึกแล้วโดยไม่สมมติว่ายอดเป็นข้อมูลครบทุกสัญญา</div>`;}
function budgetMonthBars(ps){let by={};ps.forEach(p=>by[p.procureMonth]=(by[p.procureMonth]||0)+p.plannedAmount);let max=Math.max(1,...Object.values(by));return `<div class="stack">${Object.entries(by).sort(([a],[b])=>a.localeCompare(b)).map(([m,v])=>`<div class="barrow"><span>${monthBE(m)}</span><div class="bartrack"><div class="barfill teal" style="width:${100*v/max}%"></div></div><span class="num">${million(v)} ลบ.</span></div>`).join('')||'<div class="empty">ไม่มีรายการ</div>'}</div>`;}
function renderContracts(){let rows=db.contracts.filter(c=>contains(c.number,c.vendor,c.procId,c.notes));return pghead('บริหารสัญญาและการตรวจรับ','บันทึกข้อมูลสัญญาที่เกิดขึ้นจริง เชื่อมทะเบียนจัดซื้อจัดจ้างและงบประมาณ',action('＋ เพิ่มสัญญา','addContract','teal')+action('⇩ CSV','csvContracts',''))+`<div class="cards">${metric('สัญญาที่มีข้อมูล',rows.length,'บันทึกภายในระบบนี้')}${metric('วงเงินสัญญาที่บันทึก',rows.some(c=>readNum(c.amount)!==null)?million(rows.reduce((s,c)=>s+(readNum(c.amount)||0),0))+' ลบ.':'—','ไม่ใช่มูลค่าสัญญารวมจริงทั้งหมด')}${metric('มีวันครบกำหนด',rows.filter(c=>c.deadline).length,'จากสัญญาที่กรอก')}${metric('ตรวจรับแล้ว',rows.filter(c=>c.status==='ตรวจรับแล้ว').length,'ตามข้อมูลที่ผู้ใช้กรอก')}</div>`+panel('ทะเบียนสัญญา',`<div class="tblwrap"><table class="tbl"><thead><tr><th>เลขที่สัญญา</th><th>รายการจัดซื้อ</th><th>คู่สัญญา</th><th class="right">วงเงินสัญญา</th><th class="right">เบิกจ่าย</th><th>วันครบกำหนด</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody>${rows.map(c=>`<tr><td class="strong">${esc(c.number||'—')}</td><td><button class="linkbtn" data-action="editProc" data-id="${c.procId}">${esc(c.procId)}</button></td><td>${esc(c.vendor||'—')}</td><td class="right">${baht(readNum(c.amount))}</td><td class="right">${baht(readNum(c.paid))}</td><td>${isoToBE(c.deadline)}</td><td>${tag(c.status||'ยังไม่ระบุ',c.status==='ตรวจรับแล้ว'?'teal':'grey')}</td><td>${action('แก้ไข','editContract','',c.id)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty"><div class="empty-icon">◧</div>ยังไม่มีข้อมูลสัญญา · เพิ่มเฉพาะรายการที่มีหลักฐานจริง</td></tr>'}</tbody></table></div>`,'ข้อมูลตั้งต้นไม่มีหมายเลขสัญญาหรือยอดจ่าย จึงไม่สร้างขึ้นเอง');}
function workload(){return db.assignments.reduce((acc,a)=>{let k=a.personId,planned=readNum(a.plannedHours)||0,actual=readNum(a.actualHours)||0;if(!acc[k])acc[k]={planned:0,actual:0,count:0};acc[k].planned+=planned;acc[k].actual+=actual;acc[k].count++;return acc},{});}
function renderPeople(){let people=db.people.filter(p=>contains(p.name,p.title,p.group));let wl=workload();return pghead('กำลังคนและการมอบหมาย','กำกับกำลังคน ชั่วโมงงานตามแผน ชั่วโมงทำงานจริง และภารกิจที่รับผิดชอบ',action('＋ เพิ่มบุคลากร','addPerson','teal')+action('＋ มอบหมายงาน','addAssignment',''))+`<div class="notice">ไม่ปรากฏรายชื่อบุคลากรและชั่วโมงทำงานรายบุคคลในเอกสารต้นฉบับ จึงเริ่มต้นทะเบียนนี้เป็นข้อมูลว่างเพื่อให้กรอกข้อมูลจริง</div><div class="cards">${metric('บุคลากรที่บันทึก',people.length,'รายชื่อที่บันทึกใน Dashboard')}${metric('รายการมอบหมายงาน',db.assignments.length,'ทุกเดือนที่ระบุ')}${metric('ชั่วโมงงานตามแผน',db.assignments.some(a=>readNum(a.plannedHours)!==null)?fmtNum(db.assignments.reduce((s,a)=>s+(readNum(a.plannedHours)||0),0)):'—','ผลรวมรายการมอบหมาย')}${metric('ชั่วโมงปฏิบัติงานจริง',db.assignments.some(a=>readNum(a.actualHours)!==null)?fmtNum(db.assignments.reduce((s,a)=>s+(readNum(a.actualHours)||0),0)):'—','ตามชั่วโมงที่กรอก')}</div>`+panel('ทะเบียนบุคลากรและภาระงาน',`<div class="tblwrap"><table class="tbl"><thead><tr><th>ชื่อ</th><th>กลุ่ม/บทบาท</th><th>ความจุ ชม./เดือน</th><th>มอบหมาย ชม.</th><th>ทำจริง ชม.</th><th>รายการมอบหมาย</th><th>จัดการ</th></tr></thead><tbody>${people.map(p=>{let x=wl[p.id]||{planned:0,actual:0,count:0};return `<tr><td class="strong">${esc(p.name)}</td><td>${esc(p.group||'—')}<div class="small muted">${esc(p.title||'')}</div></td><td>${fmtNum(p.capacity)}</td><td>${x.count?fmtNum(x.planned):'—'}</td><td>${x.count?fmtNum(x.actual):'—'}</td><td>${x.count}</td><td>${action('แก้ไข','editPerson','',p.id)}</td></tr>`}).join('')||'<tr><td colspan="7" class="empty">ยังไม่ได้ลงทะเบียนบุคลากร</td></tr>'}</tbody></table></div>`,'การวัดภาระงานที่ถูกต้องต้องใช้ความจุและชั่วโมงในช่วงเวลาเดียวกัน')+panel('บันทึกการมอบหมายงาน',`<div class="tblwrap"><table class="tbl"><thead><tr><th>บุคลากร</th><th>ภารกิจ</th><th>เดือน</th><th>ตามแผน (ชม.)</th><th>จริง (ชม.)</th><th>จัดการ</th></tr></thead><tbody>${db.assignments.map(a=>`<tr><td>${esc(db.people.find(p=>p.id===a.personId)?.name||'ไม่พบชื่อ')}</td><td>${esc(taskBy(a.taskId)?.name||a.taskId)}</td><td>${monthBE(a.month)}</td><td>${fmtNum(a.plannedHours)}</td><td>${fmtNum(a.actualHours)}</td><td>${action('แก้ไข','editAssignment','',a.id)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">ยังไม่มีรายการมอบหมายงาน</td></tr>'}</tbody></table></div>`);}
function getOutcomes(){return [...SEED.outcomes.map(k=>({...k,...(db.outcomes[k.id]||{}),baseline:true})),...Object.entries(db.outcomes).filter(([id])=>!SEED.outcomes.find(k=>k.id===id)).map(([id,k])=>({...k,id,baseline:false}))];}
function renderOutcomes(){let kpis=getOutcomes().filter(k=>contains(k.id,k.name,taskBy(k.workstreamId)?.name));return pghead('ผลผลิตและผลสัมฤทธิ์','ตัวชี้วัดตามแผนและผลจริงที่มีการบันทึก พร้อมแหล่งหลักฐาน',action('＋ เพิ่มตัวชี้วัด','addOutcome','teal'))+`<div class="cards">${metric('ตัวชี้วัดที่มีข้อมูล',kpis.length,'ข้อมูลตั้งต้นมี 1 เป้าหมายที่ระบุตัวเลข')}${metric('มีค่าเป้าหมาย',kpis.filter(k=>readNum(k.target)!==null).length,'ต้องอ้างอิงแผนที่อนุมัติ')}${metric('มีผลจริง',kpis.filter(k=>readNum(k.actual)!==null).length,'ต้องแนบหลักฐานประกอบ')}${metric('จำนวนหลักฐานที่บันทึก',db.evidence.filter(e=>e.relatedType==='outcome').length,'เชื่อมกับตัวชี้วัด')}</div>`+panel('ตัวชี้วัดผลสัมฤทธิ์',`<div class="panel-body"><div class="stack">${kpis.map(k=>{let target=readNum(k.target),actual=readNum(k.actual),rate=target&&actual!==null?actual/target*100:null;return `<div class="kpi-spot"><div class="inlineform" style="justify-content:space-between;align-items:flex-start"><div><div class="small muted">${esc(k.id)} · ${esc(k.workstreamId||'ไม่ระบุภารกิจ')} · ${esc(k.source||'ตัวชี้วัดผู้ใช้สร้าง')}</div><div style="font-size:15px;font-weight:900;margin:5px 0 12px">${esc(k.name)}</div></div>${action('แก้ไข','editOutcome','',k.id)}</div><div class="rec-grid"><div><span class="muted small">เป้าหมาย</span><strong style="display:block;font-size:21px">${target===null?'—':fmtNum(target)+' '+esc(k.unit||'')}</strong></div><div><span class="muted small">ผลจริงที่บันทึก</span><strong style="display:block;font-size:21px">${actual===null?'—':fmtNum(actual)+' '+esc(k.unit||'')}</strong></div><div><span class="muted small">อัตราเทียบเป้าหมาย</span><strong style="display:block;font-size:21px">${rate===null?'—':rate.toFixed(1)+'%'}</strong></div></div><div style="margin-top:10px" class="progress-track"><i style="width:${rate===null?0:Math.min(100,Math.max(0,rate))}%"></i></div><div class="small muted" style="margin-top:9px">${esc(k.notes||'ยังไม่มีรายงานผลและหลักฐานประกอบ')}</div></div>`}).join('')||'<div class="empty">ไม่มีตัวชี้วัดในตัวกรอง</div>'}</div></div>`,'เป้าหมายขยาย RNIS อีก 29 จังหวัดมาจากภาพแผน; ไม่ได้สมมติจำนวนจังหวัดที่ดำเนินการสำเร็จ')+panel('Roadmap และผลผลิตที่ต้องติดตาม',`<div class="panel-body">${milestones()}</div>`);}
function renderEvidence(){let ev=db.evidence.filter(e=>contains(e.title,e.notes,e.relatedId,e.fileName));return pghead('หลักฐานการดำเนินงาน','บันทึกไฟล์ เอกสารตรวจรับ ภาพกิจกรรม และเอกสารยืนยันผลตามโครงการ',action('＋ เพิ่มหลักฐาน','addEvidence','teal'))+`<div class="notice warn">ไฟล์แนบถูกเก็บในฐานข้อมูลของเบราว์เซอร์เครื่องนี้ (IndexedDB) ไม่ได้อัปโหลดขึ้นส่วนกลาง ใช้เมนู “สำรองข้อมูล” เพื่อส่งออกทั้งข้อมูลและไฟล์แนบก่อนเปลี่ยนเครื่องหรือล้างข้อมูลเบราว์เซอร์</div>`+`<div class="cards">${metric('รายการหลักฐาน',ev.length,'เฉพาะที่บันทึกในเครื่องนี้')}${metric('มีไฟล์แนบ',ev.filter(e=>e.hasFile).length,'ไฟล์ที่ระบุว่าจัดเก็บไว้')}${metric('เกี่ยวกับภารกิจ',ev.filter(e=>e.relatedType==='task').length,'เชื่อมรหัส I/N')}${metric('เกี่ยวกับจัดซื้อฯ / สัญญา',ev.filter(e=>['proc','contract'].includes(e.relatedType)).length,'เชื่อมรหัส P / สัญญา')}</div>`+panel('ทะเบียนหลักฐานและเอกสาร',`<div class="tblwrap"><table class="tbl"><thead><tr><th>วันที่บันทึก</th><th>ชื่อเอกสาร</th><th>เชื่อมโยง</th><th>ชื่อไฟล์</th><th>การเข้าถึง</th></tr></thead><tbody>${ev.map(e=>`<tr><td>${isoToBE(e.date)}</td><td class="namecol strong">${esc(e.title)}<div class="small muted">${esc(e.notes||'')}</div></td><td>${esc(({task:'ภารกิจ',proc:'จัดซื้อฯ',contract:'สัญญา',outcome:'ตัวชี้วัด',other:'ทั่วไป'})[e.relatedType]||'ทั่วไป')} · ${esc(e.relatedId||'—')}</td><td>${esc(e.fileName||'ไม่มีไฟล์')}</td><td><div class="inlineform">${e.hasFile?action('เปิดไฟล์','openEvidence','',e.id):''}${action('แก้ไข','editEvidence','',e.id)}</div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">ยังไม่มีหลักฐานบันทึก</td></tr>'}</tbody></table></div>`,'ควรมีหลักฐานอ้างอิงรองรับผลที่รายงานทุกเดือน');}
function renderRisks(){let rs=db.risks.filter(r=>contains(r.title,r.relatedId,r.owner,r.notes));return pghead('ความเสี่ยงและประเด็นติดตาม','บริหารรายการความเสี่ยงที่ได้รับการยืนยัน พร้อมเจ้าภาพ มาตรการ และสถานะการจัดการ',action('＋ เพิ่มความเสี่ยง','addRisk','teal'))+`<div class="notice">รายการความเสี่ยงยังไม่ถูกสร้างเป็นเหตุการณ์จริงจากการวิเคราะห์เบื้องต้น เพื่อป้องกันการเข้าใจผิด ควรบันทึกเมื่อมีการประเมินและยืนยันโดยผู้รับผิดชอบ</div>`+`<div class="cards">${metric('รายการความเสี่ยง',rs.length,'รายการที่มีการบันทึก')}${metric('ระดับสูง',rs.filter(r=>r.severity==='สูง').length,'ประเมินโดยผู้บันทึก')}${metric('กำลังแก้ไข',rs.filter(r=>r.status==='กำลังแก้ไข').length,'ตามข้อมูลที่บันทึก')}${metric('ปิดประเด็น',rs.filter(r=>r.status==='ปิดแล้ว').length,'ตามข้อมูลที่บันทึก')}</div>`+panel('Risk Register',`<div class="tblwrap"><table class="tbl"><thead><tr><th>ความเสี่ยง/ประเด็น</th><th>สัมพันธ์กับ</th><th>ระดับ</th><th>เจ้าภาพ</th><th>สถานะ</th><th>แนวทางควบคุม</th><th>จัดการ</th></tr></thead><tbody>${rs.map(r=>`<tr><td class="namecol strong">${esc(r.title)}</td><td>${esc(r.relatedId||'—')}</td><td>${tag(r.severity||'ยังไม่ประเมิน',r.severity==='สูง'?'red':r.severity==='กลาง'?'gold':'grey')}</td><td>${esc(r.owner||'—')}</td><td>${statusTag(r.status)}</td><td>${esc(r.action||'—')}</td><td>${action('แก้ไข','editRisk','',r.id)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">ยังไม่มีรายการความเสี่ยงที่ผ่านการบันทึก</td></tr>'}</tbody></table></div>`,'แยกความเสี่ยงที่ประเมินจริงออกจากข้อค้นพบเชิงวิเคราะห์ในรายงาน');}
function renderAudit(){return pghead('ศูนย์ข้อมูลและประวัติการแก้ไข','บริหารการสำรองข้อมูล กู้คืน ตรวจสอบแหล่งอ้างอิง และประวัติการบันทึกในเครื่อง')+`<div class="grid2">${panel('สำรองและนำเข้าข้อมูล',`<div class="panel-body"><div class="stack"><p class="help">ส่งออกไฟล์ JSON ที่รวมข้อมูลที่กรอก ประวัติการเปลี่ยนแปลง และไฟล์หลักฐานที่ระบบเรียกอ่านได้จากเบราว์เซอร์ จากนั้นสามารถนำไฟล์นี้เข้าใช้งานในเครื่องอื่นได้</p><div class="inlineform">${action('⇩ สำรองข้อมูลทั้งหมด','backup','primary')}${action('⇧ นำเข้าข้อมูล JSON','import','')}${action('รีเซ็ตข้อมูลที่กรอก','reset','warn')}</div><div class="notice warn">การนำเข้าจะแทนข้อมูลที่กรอกในเครื่องนี้ กรุณาสำรองก่อนทุกครั้ง โดยเฉพาะเมื่อเปลี่ยนอุปกรณ์</div></div></div>`,'ข้อมูลต้นฉบับ 35 ภารกิจและ 33 รายการจะคงเดิม')}${panel('ข้อมูลต้นฉบับและคำอธิบาย',`<div class="panel-body"><div class="stack"><div class="listline"><span>ภาพแผน YEAR ACTION PLAN 2570</span>${tag('35 ภารกิจ','blue')}</div><div class="listline"><span>แผนจัดซื้อจัดจ้างปี 2570</span>${tag('33 รายการ','teal')}</div><div class="listline"><span>วงเงินที่ตรวจสอบรวม</span><strong>110,502,300 บาท</strong></div><div class="listline"><span>สถานะร่าง TOR ตาม PDF</span><span>มี 31 / ไม่มี 2</span></div><p class="help">รหัสรายการจัดซื้อ P01–P33 เป็นรหัสจัดทำเพื่อใช้งานใน Dashboard ส่วนการจับคู่รายการงบกับภารกิจในส่วนแนะนำยังไม่ใช่ข้อมูลที่หน่วยงานยืนยัน</p><details><summary style="cursor:pointer;font-weight:850">ดูภาพแผนต้นฉบับ</summary><img class="srcpreview" src="${IMAGE_SRC}" alt="ภาพ YEAR ACTION PLAN 2570"></details></div></div>`,'ตรวจสอบจากเอกสารที่แนบมา')}</div>`+panel('ประวัติการบันทึกล่าสุด',`<div class="panel-body">${db.logs.length?db.logs.slice(0,100).map(l=>`<div class="audit"><b>${esc(l.text)}</b><p>${new Date(l.at).toLocaleString('th-TH')} · ${esc(l.kind)} ${esc(l.target)}</p></div>`).join(''):'<div class="empty">ยังไม่มีประวัติการแก้ไข</div>'}</div>`,'บันทึกเหตุการณ์ภายในเบราว์เซอร์ ไม่ใช่ Audit Log ส่วนกลางที่ป้องกันการแก้ไขได้')+`<div class="footer-note">ข้อจำกัดระบบ: เวอร์ชันนี้ไม่ใช่ฐานข้อมูลหลายผู้ใช้ ไม่มีระบบลงชื่อเข้าใช้ การอนุมัติทางอิเล็กทรอนิกส์ หรือการเชื่อม e-GP/e-Finance อัตโนมัติ การใช้งานร่วมกันอย่างเป็นทางการจำเป็นต้องมี Backend, การกำหนดสิทธิ์และระบบตรวจสอบย้อนหลังเพิ่มเติม</div>`;}
function popForm(kind,id='',month=''){
 const t=taskBy(id),p=procBy(id),z=(kind==='task'?db.task[id]:kind==='proc'?db.proc[id]:kind==='month'?db.monthly[id+':'+month]:null)||{};
 let head='',subtitle='',body='',footer='';
 const taskOptions=SEED.workstreams.map(t=>option(t.id,t.id+' · '+t.name,'')).join('');
 const procOptions=SEED.procurements.map(p=>option(p.id,p.id+' · '+p.name,'')).join('');
 const taskSelect=(nm,value)=>`<select class="f-input" name="${nm}"><option value="">— ไม่ระบุภารกิจ —</option>${SEED.workstreams.map(t=>option(t.id,t.id+' · '+t.name,value)).join('')}</select>`;
 const procSelect=(nm,value)=>`<select class="f-input" name="${nm}"><option value="">— เลือกรายการ —</option>${SEED.procurements.map(p=>option(p.id,p.id+' · '+p.name,value)).join('')}</select>`;
 if(kind==='task'&&t){head=t.id+' · '+t.name;subtitle='แก้ไขเฉพาะข้อมูลผลจริง ผู้รับผิดชอบและความเชื่อมโยง ไม่เปลี่ยนข้อมูลแผนต้นฉบับ';body=`<div class="formgrid"><div class="fgroup"><label>สถานะภารกิจ</label>${sel('status',statusList,z.status)}</div>${fld('ความก้าวหน้าจริง (%)','progress',z.progress??'','number','min="0" max="100" step="0.1" placeholder="ไม่มีข้อมูล"')}${fld('ผู้รับผิดชอบ / เจ้าภาพ','owner',z.owner||'')}${fld('วันที่คาดว่าจะส่งมอบ (ค.ศ.)','dueDate',z.dueDate||'','date')}${textarea('ผลผลิตจริง / บันทึกการดำเนินงาน','notes',z.notes||'')}<div class="fgroup full"><div class="callout"><b>การเชื่อมแผนกับงบประมาณ:</b> โปรดเปิดรายการจัดซื้อจัดจ้าง Pxx เพื่อยืนยันรหัสภารกิจที่สัมพันธ์กัน หลังยืนยันจะแสดงความเชื่อมโยงในระบบ</div></div></div>`;footer=action('＋ บันทึกผลรายเดือน','taskMonth','',id);}
 if(kind==='proc'&&p){head=p.id+' · บริหารรายการจัดซื้อจัดจ้าง';subtitle=p.name;const suggested=SEED.proposedLinks[id]||[];body=`<div class="callout"><b>ข้อมูลอ้างอิง:</b> ${esc(p.category)} · วงเงินตามแผน <b>${baht(p.plannedAmount)} บาท</b> · จัดซื้อ ${monthBE(p.procureMonth)} · ต้องการใช้งาน ${monthBE(p.requiredMonth)} · ร่าง TOR: ${p.torDraft?'มี':'ไม่มี'} (ตามเอกสาร)</div><div class="formgrid" style="margin-top:16px"><div class="fgroup"><label>สถานะจัดซื้อจัดจ้างจริง</label>${sel('status',statusList,z.status)}</div>${fld('เจ้าภาพ / ผู้รับผิดชอบ','owner',z.owner||'')}${fld('งบประมาณที่จัดสรรจริง (บาท)','allocated',z.allocated??'','number','min="0" step="0.01" placeholder="ยังไม่มีข้อมูล"')}${fld('วงเงินผูกพัน (บาท) เมื่อไม่มีข้อมูลสัญญา','committed',z.committed??'','number','min="0" step="0.01" placeholder="ยังไม่มีข้อมูล"')}${fld('ยอดเบิกจ่าย (บาท) เมื่อไม่มีข้อมูลสัญญา','paid',z.paid??'','number','min="0" step="0.01" placeholder="ยังไม่มีข้อมูล"')}<div class="fgroup"><label>ความพร้อม TOR ปัจจุบัน (ผู้ใช้บันทึก)</label>${sel('torStatus',['อยู่ระหว่างจัดทำ','จัดทำร่างแล้ว','ได้รับความเห็นชอบแล้ว','ไม่เกี่ยวข้อง'],z.torStatus)}</div>${fld('วันที่ออกสัญญา/จัดซื้อ (ค.ศ.)','contractDate',z.contractDate||'','date')}${fld('วันที่ส่งมอบที่ยืนยัน (ค.ศ.)','actualDueDate',z.actualDueDate||'','date')}${textarea('รายละเอียดความคืบหน้า / ปัญหา','notes',z.notes||'')}<div class="fgroup full"><label>ภารกิจที่เชื่อมโยงอย่างเป็นทางการ (ทำเครื่องหมายยืนยันได้หลายภารกิจ)</label><div class="checkboxlist">${SEED.workstreams.map(t=>`<label><input type="checkbox" name="links" value="${t.id}" ${(z.links||[]).includes(t.id)?'checked':''}> ${t.id} · ${esc(t.name)}</label>`).join('')}</div><p class="hint">ข้อเสนอเชื่อมโยงจากการวิเคราะห์ชื่อรายการ (ยังไม่ยืนยัน): ${suggested.map(x=>`<span class="scrolltag">${x}</span>`).join(' ')||'—'} · ข้อเสนอเหล่านี้ไม่ได้ทำเครื่องหมายอัตโนมัติ</p></div></div>`;footer=action('＋ เพิ่มสัญญาที่เชื่อมรายการนี้','contractForProc','',id);}
 if(kind==='month'){const m=month||fiscalMonths[0],v=taskBy(id);head='บันทึกผลรายเดือน · '+(v?v.id+' '+v.name:'เลือกภารกิจ');subtitle='เป็นข้อมูลผลปฏิบัติจริง แยกจากระดับกิจกรรมตามแผน';body=`<div class="formgrid"><div class="fgroup"><label>ภารกิจ</label>${taskSelect('taskId',id)}</div><div class="fgroup"><label>เดือนปีงบประมาณ</label><select name="month" class="f-input">${fiscalMonths.map(x=>option(x,monthBE(x),m)).join('')}</select></div>${fld('ความก้าวหน้าเดือนนี้ (%)','progress',z.progress??'','number','min="0" max="100" step="0.1" placeholder="ไม่มีข้อมูล"')}${fld('วันที่รายงาน (ค.ศ.)','reportDate',z.reportDate||new Date().toISOString().slice(0,10),'date')}${textarea('ผลงานรายเดือน / หลักฐานอ้างอิง','notes',z.notes||'')}</div>`;}
 if(kind==='contract'){let c=db.contracts.find(x=>x.id===id)||{};head=(id?'แก้ไข':'เพิ่ม')+'ข้อมูลสัญญา';subtitle='กรอกข้อมูลจากสัญญาหรือเอกสารจริง';body=`<div class="formgrid"><div class="fgroup full"><label>รายการจัดซื้อจัดจ้างที่สัมพันธ์</label>${procSelect('procId',c.procId||((typeof id==='string'&&id.startsWith('P'))?id:''))}</div>${fld('เลขที่สัญญา / ใบสั่งซื้อ','number',c.number||'','text','required')}${fld('ชื่อผู้รับจ้าง/คู่สัญญา','vendor',c.vendor||'')}${fld('วงเงินตามสัญญา (บาท)','amount',c.amount??'','number','min="0" step="0.01"')}${fld('ยอดจ่ายจริงสะสม (บาท)','paid',c.paid??'','number','min="0" step="0.01"')}${fld('วันที่ลงนามสัญญา (ค.ศ.)','signed',c.signed||'','date')}${fld('กำหนดส่งมอบตามสัญญา (ค.ศ.)','deadline',c.deadline||'','date')}<div class="fgroup"><label>สถานะสัญญา</label>${sel('status',['เตรียมทำสัญญา','ลงนามแล้ว','อยู่ระหว่างดำเนินการ','ส่งมอบแล้ว','รอตรวจรับ','ตรวจรับแล้ว','สิ้นสุดสัญญา','ยกเลิก'],c.status)}</div>${fld('ผู้ควบคุมสัญญา','owner',c.owner||'')}${textarea('ขอบเขต/งวดงาน/หมายเหตุ','notes',c.notes||'')}</div>`;footer=id&&db.contracts.find(x=>x.id===id)?action('ลบสัญญา','delContract','warn',id):'';}
 if(kind==='person'){let u=db.people.find(x=>x.id===id)||{};head=(id?'แก้ไข':'เพิ่ม')+'บุคลากร';subtitle='บันทึกเฉพาะข้อมูลที่จำเป็นสำหรับการบริหารงาน';body=`<div class="formgrid">${fld('ชื่อ-สกุล / ชื่อที่ใช้ในแผน','name',u.name||'','text','required')}${fld('บทบาท / ตำแหน่ง','title',u.title||'')}<div class="fgroup"><label>กลุ่มงาน</label>${sel('group',['ITCO','NDEMS','อื่น ๆ'],u.group)}</div>${fld('ขีดความสามารถ (ชั่วโมงต่อเดือน)','capacity',u.capacity??'','number','min="0" step="0.5" placeholder="เว้นว่างได้"')}${textarea('หมายเหตุด้านกำลังคน','notes',u.notes||'')}</div>`;footer=id?action('ลบข้อมูลบุคลากร','delPerson','warn',id):'';}
 if(kind==='assignment'){let a=db.assignments.find(x=>x.id===id)||{};head=(id?'แก้ไข':'เพิ่ม')+'รายการมอบหมายงาน';subtitle='แยกชั่วโมงตามแผนและชั่วโมงดำเนินการจริง';body=`<div class="formgrid"><div class="fgroup"><label>บุคลากร</label><select class="f-input" name="personId" required><option value="">— เลือกผู้รับผิดชอบ —</option>${db.people.map(p=>option(p.id,p.name,p.id===a.personId?p.id:a.personId)).join('')}</select></div><div class="fgroup"><label>ภารกิจ</label>${taskSelect('taskId',a.taskId)}</div><div class="fgroup"><label>เดือน</label><select class="f-input" name="month">${fiscalMonths.map(m=>option(m,monthBE(m),a.month||fiscalMonths[0])).join('')}</select></div>${fld('ชั่วโมงงานตามแผน','plannedHours',a.plannedHours??'','number','min="0" step="0.5"')}${fld('ชั่วโมงปฏิบัติจริง','actualHours',a.actualHours??'','number','min="0" step="0.5"')}${textarea('รายละเอียดงานที่มอบหมาย','notes',a.notes||'')}</div>`;footer=id?action('ลบรายการมอบหมาย','delAssignment','warn',id):'';}
 if(kind==='outcome'){let a=getOutcomes().find(x=>x.id===id)||{};head=(id?'แก้ไข':'เพิ่ม')+'ตัวชี้วัดผลสัมฤทธิ์';subtitle=a.baseline?'เป้าหมายตั้งต้นจากภาพ YEAR ACTION PLAN 2570':'กรอกเป้าหมายจากเอกสารที่อ้างอิงได้';body=`<div class="formgrid"><div class="fgroup full">${fld('ชื่อตัวชี้วัด','name',a.name||'','text','required')}</div><div class="fgroup"><label>ภารกิจที่เกี่ยวข้อง</label>${taskSelect('workstreamId',a.workstreamId)}</div>${fld('หน่วยนับ','unit',a.unit||'')}${fld('ค่าเป้าหมาย','target',a.target??'','number','min="0" step="0.01"')}${fld('ผลจริง','actual',a.actual??'','number','min="0" step="0.01" placeholder="ยังไม่มีหลักฐาน"')}<div class="fgroup"><label>เดือนเป้าหมาย</label><select class="f-input" name="due"><option value="">ยังไม่กำหนด</option>${fiscalMonths.map(m=>option(m,monthBE(m),a.due)).join('')}</select></div>${fld('แหล่งที่มา / เอกสารอ้างอิง','source',a.source||'')}${textarea('ผลการดำเนินงานและการรับรอง','notes',a.notes||'')}</div>`;footer=id&&!a.baseline?action('ลบตัวชี้วัด','delOutcome','warn',id):'';}
 if(kind==='evidence'){let e=db.evidence.find(x=>x.id===id)||{};head=(id?'แก้ไข':'เพิ่ม')+'หลักฐานการดำเนินงาน';subtitle='สามารถแนบไฟล์ที่บันทึกไว้ในเบราว์เซอร์ พร้อมข้อมูลอ้างอิง';body=`<div class="formgrid">${fld('ชื่อหลักฐาน','title',e.title||'','text','required')}${fld('วันที่บันทึก','date',e.date||new Date().toISOString().slice(0,10),'date')}<div class="fgroup"><label>ประเภทงานที่เกี่ยวข้อง</label><select class="f-input" name="relatedType">${[['task','ภารกิจ'],['proc','จัดซื้อจัดจ้าง'],['contract','สัญญา'],['outcome','ตัวชี้วัด'],['other','ทั่วไป']].map(([v,l])=>option(v,l,e.relatedType||'task')).join('')}</select></div>${fld('รหัสที่เกี่ยวข้อง (Ixx, Nxx, Pxx หรือรหัสสัญญา)','relatedId',e.relatedId||'')}${textarea('รายละเอียดหรือสาระสำคัญ','notes',e.notes||'')}<div class="fgroup full"><label>แนบไฟล์เอกสาร (สูงสุด 10 MB ต่อไฟล์)</label><input class="f-input" type="file" name="file"><div class="hint">${e.hasFile?'มีไฟล์เดิม: '+esc(e.fileName):'หากไม่แนบไฟล์ จะเป็นบันทึกหลักฐานแบบข้อความ'} · ห้ามแนบข้อมูลผู้ป่วยหรือข้อมูลส่วนบุคคลที่ไม่จำเป็น</div></div></div>`;footer=id?action('ลบรายการและไฟล์หลักฐาน','delEvidence','warn',id):'';}
 if(kind==='risk'){let r=db.risks.find(x=>x.id===id)||{};head=(id?'แก้ไข':'เพิ่ม')+'ความเสี่ยงและประเด็นติดตาม';subtitle='บันทึกผลการประเมินที่ผู้รับผิดชอบตรวจสอบแล้ว';body=`<div class="formgrid"><div class="fgroup full">${fld('ประเด็นความเสี่ยง','title',r.title||'','text','required')}</div>${fld('ภารกิจหรือจัดซื้อที่เกี่ยวข้อง','relatedId',r.relatedId||'')}<div class="fgroup"><label>ระดับความเสี่ยง</label>${sel('severity',['สูง','กลาง','ต่ำ'],r.severity)}</div>${fld('เจ้าภาพ','owner',r.owner||'')}<div class="fgroup"><label>สถานะการจัดการ</label>${sel('status',['ยังไม่ประเมิน','เปิดประเด็น','กำลังแก้ไข','ติดตามผล','ปิดแล้ว'],r.status)}</div>${fld('กำหนดแก้ไข (ค.ศ.)','due',r.due||'','date')}${textarea('มาตรการลดความเสี่ยง / การจัดการ','action',r.action||'')}${textarea('หลักฐานหรือคำอธิบาย','notes',r.notes||'')}</div>`;footer=id?action('ลบประเด็น','delRisk','warn',id):'';}
 if(!head){notify('ไม่พบข้อมูลรายการ',true);return;}
 document.getElementById('modalRoot').innerHTML=`<div class="modal-cover" id="modalCover"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>${esc(head)}</h2><p>${esc(subtitle)}</p></div><button type="button" class="btn sm" data-action="close">✕</button></div><form id="editForm" data-kind="${kind}" data-id="${attr(id)}" data-month="${attr(month)}"><div class="modal-content">${body}</div><div class="modal-foot">${footer}<button type="button" class="btn" data-action="close">ยกเลิก</button><button class="btn primary" type="submit">✓ บันทึกข้อมูล</button></div></form></div></div>`;
 document.querySelector('#modalRoot .modal')?.scrollTo(0,0);
}
function readForm(form){let fd=new FormData(form),vals=Object.fromEntries(fd.entries());return vals;}
async function saveForm(form){let kind=form.dataset.kind,id=form.dataset.id,month=form.dataset.month,vals=readForm(form),now=new Date().toISOString();
 if(kind==='task'){let progress=vals.progress===''?null:Number(vals.progress);if(progress!==null&&(progress<0||progress>100))return notify('ความก้าวหน้าต้องอยู่ระหว่าง 0–100%',true);db.task[id]={status:vals.status||'',progress,owner:vals.owner.trim(),dueDate:vals.dueDate,notes:vals.notes,updated:now};saveLog('ภารกิจ',id,'บันทึกสถานะ '+id+' '+(vals.status||'ยังไม่รายงาน'));}
 if(kind==='proc'){let numNames=['allocated','committed','paid'];for(let n of numNames)if(vals[n]!==''&&Number(vals[n])<0)return notify('จำนวนเงินต้องไม่ติดลบ',true);let links=[...form.querySelectorAll('input[name="links"]:checked')].map(e=>e.value);db.proc[id]={status:vals.status,owner:vals.owner.trim(),allocated:vals.allocated===''?null:Number(vals.allocated),committed:vals.committed===''?null:Number(vals.committed),paid:vals.paid===''?null:Number(vals.paid),torStatus:vals.torStatus,contractDate:vals.contractDate,actualDueDate:vals.actualDueDate,notes:vals.notes,links,updated:now};saveLog('จัดซื้อจัดจ้าง',id,'ปรับปรุงทะเบียน '+id+' (เชื่อม '+links.length+' ภารกิจ)');}
 if(kind==='month'){id=vals.taskId;month=vals.month;if(!id)return notify('โปรดเลือกภารกิจ',true);if(vals.progress!==''&&(Number(vals.progress)<0||Number(vals.progress)>100))return notify('ความก้าวหน้าต้องอยู่ระหว่าง 0–100%',true);db.monthly[id+':'+month]={progress:vals.progress===''?null:Number(vals.progress),reportDate:vals.reportDate,notes:vals.notes,updated:now};saveLog('รายเดือน',id,`บันทึกผลงาน ${id} ${monthBE(month)}`);}
 if(kind==='contract'){if(!vals.procId)return notify('โปรดเลือกรายการจัดซื้อที่สัมพันธ์',true);if(!vals.number)return notify('โปรดระบุเลขที่สัญญา',true);let item={id:id&&db.contracts.some(x=>x.id===id)?id:uid('CT'),procId:vals.procId,number:vals.number,vendor:vals.vendor,amount:vals.amount===''?null:Number(vals.amount),paid:vals.paid===''?null:Number(vals.paid),signed:vals.signed,deadline:vals.deadline,status:vals.status,owner:vals.owner,notes:vals.notes,updated:now};if((item.amount!==null&&item.amount<0)||(item.paid!==null&&item.paid<0))return notify('จำนวนเงินต้องไม่ติดลบ',true);upsert('contracts',item);saveLog('สัญญา',item.id,'บันทึกสัญญา '+item.number);}
 if(kind==='person'){let item={id:id||uid('HR'),name:vals.name.trim(),title:vals.title,group:vals.group,capacity:vals.capacity===''?null:Number(vals.capacity),notes:vals.notes,updated:now};upsert('people',item);saveLog('บุคลากร',item.id,'บันทึกบุคลากร '+item.name);}
 if(kind==='assignment'){if(!vals.personId||!vals.taskId)return notify('โปรดระบุบุคลากรและภารกิจ',true);let item={id:id||uid('AS'),personId:vals.personId,taskId:vals.taskId,month:vals.month,plannedHours:vals.plannedHours===''?null:Number(vals.plannedHours),actualHours:vals.actualHours===''?null:Number(vals.actualHours),notes:vals.notes,updated:now};if((item.plannedHours!==null&&item.plannedHours<0)||(item.actualHours!==null&&item.actualHours<0))return notify('ชั่วโมงต้องไม่ติดลบ',true);upsert('assignments',item);saveLog('มอบหมายงาน',item.id,'บันทึกชั่วโมงการมอบหมาย '+item.taskId);}
 if(kind==='outcome'){let old=getOutcomes().find(x=>x.id===id),item={name:vals.name,workstreamId:vals.workstreamId,unit:vals.unit,target:vals.target===''?null:Number(vals.target),actual:vals.actual===''?null:Number(vals.actual),due:vals.due,source:vals.source,notes:vals.notes,updated:now};let key=id||uid('K');db.outcomes[key]=item;saveLog('ตัวชี้วัด',key,'บันทึกตัวชี้วัด '+item.name);}
 if(kind==='risk'){let item={id:id||uid('RK'),title:vals.title,relatedId:vals.relatedId,severity:vals.severity,owner:vals.owner,status:vals.status,due:vals.due,action:vals.action,notes:vals.notes,updated:now};upsert('risks',item);saveLog('ความเสี่ยง',item.id,'บันทึกความเสี่ยง '+item.title);}
 if(kind==='evidence'){let file=form.querySelector('input[name="file"]')?.files?.[0];if(file&&file.size>10*1024*1024)return notify('ไฟล์ใหญ่เกิน 10 MB',true);let old=db.evidence.find(x=>x.id===id);let item={id:id||uid('EV'),title:vals.title,date:vals.date,relatedType:vals.relatedType,relatedId:vals.relatedId,notes:vals.notes,fileName:old?.fileName||'',fileSize:old?.fileSize||0,hasFile:old?.hasFile||false,updated:now};if(file){try{await storeBlob(item.id,file);item.fileName=file.name;item.fileSize=file.size;item.hasFile=true;}catch(e){return notify('ไม่สามารถจัดเก็บไฟล์แนบในเบราว์เซอร์ได้ โปรดลองบน HTTPS',true);}}upsert('evidence',item);saveLog('หลักฐาน',item.id,'บันทึกหลักฐาน '+item.title);}
 closeModal();render();notify('บันทึกข้อมูลแล้ว');
}
function uid(prefix){return prefix+'-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,6).toUpperCase()}
function upsert(list,item){let idx=db[list].findIndex(x=>x.id===item.id);if(idx<0)db[list].push(item);else db[list][idx]=item;}
function closeModal(){document.getElementById('modalRoot').innerHTML='';}
function openQuick(){document.getElementById('modalRoot').innerHTML=`<div class="modal-cover"><div class="modal" role="dialog" aria-modal="true" style="max-width:530px"><div class="modal-head"><div><h2>เลือกข้อมูลที่ต้องการบันทึก</h2><p>เพิ่มข้อมูลผลการดำเนินงานจริงลงในทะเบียนกลาง</p></div><button class="btn sm" data-action="close">✕</button></div><div class="modal-content"><div class="stack">${[['monthQuick','ผลการดำเนินงานรายเดือน'],['addContract','สัญญา / ตรวจรับ'],['addPerson','บุคลากร'],['addAssignment','มอบหมายงาน / ชั่วโมง'],['addOutcome','ตัวชี้วัดผลสัมฤทธิ์'],['addEvidence','หลักฐานและเอกสาร'],['addRisk','ความเสี่ยง / ประเด็น']].map(([act,l])=>`<button data-action="${act}" class="btn" style="justify-content:flex-start">＋ ${l}</button>`).join('')}</div></div></div></div>`;}
function confirmDelete(list,id,title,related){if(!confirm('ยืนยันลบข้อมูล '+title+' ? การดำเนินการนี้ไม่สามารถย้อนกลับได้หากไม่มีไฟล์สำรอง'))return;db[list]=db[list].filter(x=>x.id!==id);if(related)related();saveLog('ลบข้อมูล',id,'ลบ '+title);closeModal();render();notify('ลบรายการแล้ว');}
function unlinkedSummary(){return SEED.procurements.filter(p=>!db.proc[p.id]?.links?.length).length;}
// Evidence binary store: local browser only. Metadata is in localStorage.
let attachmentDB=null;
function openBlobDB(){if(attachmentDB)return Promise.resolve(attachmentDB);return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(new Error('IndexedDB unavailable'));let req=indexedDB.open('NIEMS_PIM_2570_Evidence',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onerror=()=>reject(req.error);req.onsuccess=()=>{attachmentDB=req.result;resolve(attachmentDB)}});}
async function storeBlob(id,file){let d=await openBlobDB();return new Promise((resolve,reject)=>{let tx=d.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});}
async function getBlob(id){let d=await openBlobDB();return new Promise((resolve,reject)=>{let tx=d.transaction('files','readonly');let req=tx.objectStore('files').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});}
async function delBlob(id){try{let d=await openBlobDB();return new Promise((res,rej)=>{let tx=d.transaction('files','readwrite');tx.objectStore('files').delete(id);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}catch(e){console.warn(e)}}
const blobToBase64=b=>new Promise((resolve,reject)=>{let fr=new FileReader();fr.onload=()=>resolve(String(fr.result).split(',')[1]);fr.onerror=()=>reject(fr.error);fr.readAsDataURL(b)});
function base64Blob(base64,type){let binary=atob(base64),l=binary.length,chunk=8192,arrays=[];for(let i=0;i<l;i+=chunk){let s=binary.slice(i,i+chunk),a=new Uint8Array(s.length);for(let j=0;j<s.length;j++)a[j]=s.charCodeAt(j);arrays.push(a)}return new Blob(arrays,{type:type||'application/octet-stream'})}
function downloadBlob(blob,name){let href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(href),15000)}
function downloadText(text,name,type='application/json;charset=utf-8'){downloadBlob(new Blob([text],{type}),name)}
async function exportBackup(){notify('กำลังรวบรวมข้อมูลและไฟล์แนบสำหรับการสำรองข้อมูล');let data={format:'NIEMS_PIM_2570_BACKUP',version:1,exportedAt:new Date().toISOString(),sourceFingerprint:{countWorkstreams:35,countProcurements:33,totalPlan:110502300},state:JSON.parse(JSON.stringify(db)),attachments:{}};let fails=0;for(let e of db.evidence){if(e.hasFile){try{let f=await getBlob(e.id);if(f)data.attachments[e.id]={filename:e.fileName,type:f.type||'application/octet-stream',base64:await blobToBase64(f)};else fails++;}catch(err){fails++;}}}downloadText(JSON.stringify(data),'NIEMS_PIM_2570_Backup_'+new Date().toISOString().slice(0,10)+'.json');notify('ส่งออกไฟล์สำรองแล้ว'+(fails?' · ไฟล์แนบที่ไม่พบ '+fails+' รายการ':''));}
async function importBackup(file){if(!file)return;let parsed;try{parsed=JSON.parse(await file.text())}catch(e){return notify('ไฟล์ JSON ไม่ถูกต้อง',true)}if(parsed.format!=='NIEMS_PIM_2570_BACKUP'||parsed.version!==1||!parsed.state||!parsed.sourceFingerprint||parsed.sourceFingerprint.totalPlan!==110502300)return notify('ไม่ใช่ไฟล์สำรองของ Dashboard รุ่นนี้',true);if(!confirm('การนำเข้าจะแทนข้อมูลที่บันทึกในเครื่องนี้ทั้งหมด โปรดยืนยันว่ามีไฟล์สำรองแล้ว'))return;let data={...emptyState(),...parsed.state};for(let n of ['contracts','people','assignments','evidence','risks','logs'])if(!Array.isArray(data[n]))return notify('โครงสร้างไฟล์สำรองไม่ถูกต้อง',true);let binaryFailed=0;for(let [id,obj] of Object.entries(parsed.attachments||{})){try{await storeBlob(id,base64Blob(obj.base64,obj.type))}catch(e){binaryFailed++}}db=data;save();render();notify('นำเข้าข้อมูลสำเร็จ'+(binaryFailed?' แต่บางไฟล์แนบไม่สามารถนำเข้าได้':''));}
function csvQuote(v){let s=v===null||v===undefined?'':String(v);if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function exportCSV(type){let header=[],rows=[];if(type==='csvProc'){header=['รหัส','ประเภท','รายการ','วงเงินแผน','เดือนจัดซื้อ','เดือนต้องการใช้งาน','ร่าง TOR','สถานะจริง','ผู้รับผิดชอบ','รหัสภารกิจเชื่อม'];rows=filteredProcs().map(p=>[p.id,p.category,p.name,p.plannedAmount,p.procureMonth,p.requiredMonth,p.torDraft?'มี':'ไม่มี',db.proc[p.id]?.status||'',db.proc[p.id]?.owner||'',(db.proc[p.id]?.links||[]).join('|')]);}if(type==='csvBudget'){header=['รหัส','รายการ','วงเงินแผน','งบได้รับจัดสรรจริง','วงเงินผูกพันที่บันทึก','เบิกจ่ายที่บันทึก'];rows=SEED.procurements.map(p=>{let x=getProcActual(p);return [p.id,p.name,p.plannedAmount,x.allocated,x.committed,x.paid]});}if(type==='csvContracts'){header=['สัญญา','รหัสรายการจัดซื้อ','คู่สัญญา','วงเงิน','เบิกจ่าย','วันลงนาม','วันครบกำหนด','สถานะ'];rows=db.contracts.map(c=>[c.number,c.procId,c.vendor,c.amount,c.paid,c.signed,c.deadline,c.status]);}downloadText('\ufeff'+[header,...rows].map(row=>row.map(csvQuote).join(',')).join('\r\n'),'NIEMS_2570_'+type+'.csv','text/csv;charset=utf-8');notify('ส่งออกไฟล์ CSV แล้ว');}
async function openEvidence(id){let e=db.evidence.find(x=>x.id===id);if(!e?.hasFile)return notify('ไม่พบไฟล์แนบสำหรับรายการนี้',true);try{let blob=await getBlob(id);if(!blob)return notify('ข้อมูลไฟล์แนบหายไปจากเบราว์เซอร์ กรุณากู้คืนจากไฟล์สำรอง',true);downloadBlob(blob,e.fileName||'evidence.bin');}catch(err){notify('ไม่สามารถอ่านไฟล์แนบได้',true)}}
async function resetInputs(){if(!confirm('ต้องการล้างข้อมูลที่บันทึกทั้งหมดใน Dashboard นี้ (ไม่รวมข้อมูลต้นฉบับ) ใช่หรือไม่?'))return;if(!confirm('ยืนยันครั้งสุดท้าย: การลบนี้ไม่สามารถกู้คืนได้หากไม่ได้สำรองไฟล์ JSON'))return;for(let e of db.evidence)await delBlob(e.id);db=emptyState();save();render();notify('รีเซ็ตข้อมูลที่บันทึกแล้ว');}
async function doAction(act,id='',el){switch(act){case 'addquick':openQuick();break;case 'close':closeModal();break;case 'editTask':popForm('task',id);break;case 'editProc':popForm('proc',id);break;case 'monthQuick':popForm('month','',fiscalMonths[0]);break;case 'editMonth':popForm('month',id,el?.dataset.month);break;case 'taskMonth':popForm('month',id,fiscalMonths[0]);break;case 'addContract':popForm('contract');break;case 'contractForProc':popForm('contract');setTimeout(()=>{let s=document.querySelector('select[name="procId"]');if(s)s.value=id},0);break;case 'editContract':popForm('contract',id);break;case 'addPerson':popForm('person');break;case 'editPerson':popForm('person',id);break;case 'addAssignment':if(!db.people.length){notify('โปรดเพิ่มข้อมูลบุคลากรก่อนมอบหมายงาน',true);popForm('person');}else popForm('assignment');break;case 'editAssignment':popForm('assignment',id);break;case 'addOutcome':popForm('outcome');break;case 'editOutcome':popForm('outcome',id);break;case 'addEvidence':popForm('evidence');break;case 'editEvidence':popForm('evidence',id);break;case 'openEvidence':await openEvidence(id);break;case 'addRisk':popForm('risk');break;case 'editRisk':popForm('risk',id);break;case 'delContract':confirmDelete('contracts',id,'สัญญา');break;case 'delPerson':confirmDelete('people',id,'บุคลากร',()=>db.assignments=db.assignments.filter(a=>a.personId!==id));break;case 'delAssignment':confirmDelete('assignments',id,'รายการมอบหมาย');break;case 'delOutcome':if(confirm('ยืนยันลบตัวชี้วัดนี้?')){delete db.outcomes[id];saveLog('ลบตัวชี้วัด',id,'ลบตัวชี้วัด');closeModal();render()}break;case 'delEvidence':confirmDelete('evidence',id,'หลักฐาน',()=>delBlob(id));break;case 'delRisk':confirmDelete('risks',id,'ความเสี่ยง');break;case 'backup':await exportBackup();break;case 'import':document.getElementById('importFile').click();break;case 'reset':await resetInputs();break;case 'ganttf':ganttGroup=id;render();break;case 'csvProc':case 'csvBudget':case 'csvContracts':exportCSV(act);break;}}
function installHandlers(){document.addEventListener('click',async event=>{const go=event.target.closest('[data-go]');if(go){page=go.dataset.go;document.getElementById('sidebar').classList.remove('mobile');render();window.scrollTo(0,0);return}const btn=event.target.closest('[data-action]');if(btn){event.preventDefault();await doAction(btn.dataset.action,btn.dataset.id||'',btn);return}if(event.target.id==='modalCover'||(event.target.classList?.contains('modal-cover')&&event.target===event.currentTarget))closeModal();});document.addEventListener('submit',async event=>{if(event.target.id==='editForm'){event.preventDefault();await saveForm(event.target)}});document.getElementById('globalSearch').addEventListener('input',e=>{search=e.target.value.trim();render()});document.getElementById('globalGroup').addEventListener('change',e=>{group=e.target.value;render()});document.getElementById('menubtn').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('mobile'));document.addEventListener('change',e=>{if(e.target.id==='procFilter'){procFilter=e.target.value;render()}if(e.target.id==='budgetCategory'){budgetCategory=e.target.value;render()}});document.getElementById('importFile').addEventListener('change',async e=>{await importBackup(e.target.files?.[0]);e.target.value=''});window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});}
load();installHandlers();render();
